import React, { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { useNavigate } from "react-router-dom";
import DashboardSwitcher from "../components/previews/DashboardSwitcher";
import HRPreview from "../components/previews/HRPreview";
import SalesPreview from "../components/previews/SalesPreview";
import ProjectsPreview from "../components/previews/ProjectsPreview";
import FinancePreview from "../components/previews/FinancePreview";
import AnalyticsPreview from "../components/previews/AnalyticsPreview";
import hrImg from "../assets/images/hr.jpeg";
import salesImg from "../assets/images/sales.jpeg";
import projectImg from "../assets/images/project.jpeg";
import financeImg from "../assets/images/finance.jpeg";
import analyticsImg from "../assets/images/analystics.jpeg";
// Converted from the AMINOID static HTML/CSS/JS landing page.
// CSS is injected verbatim via a <style> tag; the original vanilla-JS
// behavior (theme toggle, canvas network background, scroll reveals,
// magnetic buttons, ticker, deck rotation, portfolio/why grids) runs
// unchanged inside useEffect, since dangerouslySetInnerHTML produces
// real DOM nodes that the original ID/class-based selectors still find.

const CSS = `
  a{cursor:pointer;}
  :root{
    --ink:#E8ECFB;
    --ink-soft:#8892B0;
    --ink-faint:#55617F;
    --paper:#0F172A;
    --card:#121A2E;
    --line:rgba(79,70,229,0.12);
    --indigo:#4338CA;
    --indigo-2:#4F46E5;
    --violet:#6D5BD0;
    --blue:#3B82F6;
    --emerald:#10B981;
    --grad: linear-gradient(115deg,var(--indigo-2) 0%,var(--violet) 55%,var(--blue) 100%);
    --grad-soft: linear-gradient(115deg, rgba(79,70,229,.10), rgba(109,91,208,.10) 55%, rgba(59,130,246,.10));
    --shadow-lg: 0 30px 70px -30px rgba(0,0,0,.55);
    --shadow-sm: 0 10px 30px -14px rgba(0,0,0,.40);
    --radius-lg: 26px;
    --radius-md: 18px;
    --card-overlay: linear-gradient(rgba(18, 26, 46, 0.1) 0%, rgba(18, 26, 46, 0.75) 100%);
  }

  *{box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{
    margin:0;
    background:var(--paper);
    color:var(--ink);
    font-family:'Inter',system-ui,sans-serif;
    -webkit-font-smoothing:antialiased;
    overflow-x:hidden;
  }
  img{max-width:100%;display:block;}
  a{text-decoration:none;color:inherit;}
  ul{list-style:none;margin:0;padding:0;}
  button{font-family:inherit;}

  ::selection{background:var(--violet);color:#fff;}

  .display{font-family:'Space Grotesk',sans-serif;}
  .mono{font-family:'IBM Plex Mono',monospace;}

  .grad-text{
    background:var(--grad);
    -webkit-background-clip:text;
    background-clip:text;
    color:transparent;
  }

  .wrap{max-width:1280px;margin:0 auto;padding-inline:56px;}

  .eyebrow{
    display:inline-flex;align-items:center;gap:10px;
    font-family:'IBM Plex Mono',monospace;
    font-size:12.5px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;
    color:var(--indigo);
    margin-bottom:18px;
  }
  .eyebrow::before{content:'';width:7px;height:7px;border-radius:2px;background:var(--grad);display:inline-block;transform:rotate(45deg);}

  .section-h2{
    font-size:clamp(2rem,3.6vw,3.25rem);
    line-height:1.03;
    letter-spacing:-0.02em;
    font-weight:700;
    margin:0 0 20px;
  }
  .section-sub{
    font-size:17px;line-height:1.65;color:var(--ink-soft);max-width:560px;margin:0;
  }

  .reveal{opacity:0;transform:translateY(28px);transition:opacity .7s cubic-bezier(.22,1,.36,1),transform .7s cubic-bezier(.22,1,.36,1);}
  .reveal.in-view{opacity:1;transform:none;}

  /* ---------------- SPLIT-TEXT WORD REVEAL (blur-in, staggered) ---------------- */
  .split-word{
    display:inline-block;
    opacity:0;
    filter:blur(11px);
    transform:translateY(46%) scale(1.05);
    transition:opacity .75s cubic-bezier(.22,1,.36,1),filter .75s cubic-bezier(.22,1,.36,1),transform .75s cubic-bezier(.22,1,.36,1);
    transition-delay:var(--wd,0ms);
    will-change:opacity,filter,transform;
  }
  .split-word.in-view{opacity:1;filter:blur(0);transform:none;}

  /* ---------------- MAGNETIC BUTTON PULL ---------------- */
  .magnetic{transition:transform .35s cubic-bezier(.22,1,.36,1);}

  /* ---------------- NATIVE SCROLL-DRIVEN REVEAL (CSS animation-timeline) ---------------- */
  @keyframes scrollFadeIn{
    from{opacity:0;transform:translateY(46px) scale(.94);filter:blur(7px);}
    to{opacity:1;transform:none;filter:blur(0);}
  }
  @supports (animation-timeline: view()) {
    .p-card.reveal, .w-card.reveal, .ind-chip.reveal, .price-card.reveal{
      opacity:1;transform:none;transition:none;
      animation:scrollFadeIn linear both;
      animation-timeline:view();
      animation-range:entry 0% cover 32%;
    }
  }

  /* ---------------- 3D NETWORK BACKGROUND ---------------- */
  .network-bg{
    position:fixed;
    inset:0;
    z-index:-1;
    pointer-events:none;
    opacity:.9;
  }

  @media (prefers-reduced-motion: reduce){
    *{animation-duration:.001ms !important;animation-iteration-count:1 !important;transition-duration:.001ms !important;}
    html{scroll-behavior:auto;}
    .split-word{opacity:1;filter:none;transform:none;}
    .network-bg{opacity:.55;}
  }

  /* ---------------- NAV ---------------- */
  #product,#features,#pricing,#industries,#contact{scroll-margin-top:96px;}
  nav{
    position:sticky;top:0;z-index:100;
    display:flex;align-items:center;justify-content:space-between;
    padding:20px 56px;
    background:var(--paper);
    backdrop-filter:blur(14px);
    -webkit-backdrop-filter:blur(14px);
    border-bottom:1px solid transparent;
    transition:border-color .3s, box-shadow .3s, padding .3s;
  }
  nav.scrolled{border-color:var(--line);box-shadow:0 8px 30px -20px rgba(0,0,0,.45);padding:14px 56px;}
  .nav-logo{display:flex;align-items:center;gap:11px;font-family:'Space Grotesk';font-weight:700;font-size:19px;letter-spacing:-.01em;}
  .nav-logo img{width:30px;height:30px;border-radius:8px;}
  .nav-links{display:flex;gap:34px;font-size:14.5px;font-weight:500;}
  .nav-links a{color:var(--ink-soft);position:relative;padding:4px 0;transition:color .2s;}
  .nav-links a:hover, .nav-links a.active{color:var(--ink);}
  .nav-links a::after{content:'';position:absolute;left:0;bottom:0;width:0;height:2px;background:var(--grad);transition:width .25s;}
  .nav-links a:hover::after{width:100%;}
  .nav-actions{display:flex;align-items:center;gap:14px;}
  .btn-ghost{font-size:14.5px;font-weight:600;color:var(--ink);padding:9px 4px;}
  .btn-pill{
    font-size:14px;font-weight:600;color:#fff;background:#0B1222;
    padding:11px 22px;border-radius:999px;transition:transform .25s,box-shadow .25s,background .25s;
  }
  .btn-pill:hover{background:var(--indigo);transform:translateY(-2px);box-shadow:var(--shadow-sm);}
  .hamburger{display:none;background:none;border:1.5px solid var(--line);border-radius:10px;width:40px;height:40px;align-items:center;justify-content:center;cursor:pointer;}
  .hamburger svg{stroke:var(--ink);}
  .mobile-menu{
    display:none;position:fixed;inset:0 0 auto 0;top:64px;z-index:99;
    background:var(--paper);border-bottom:1px solid var(--line);
    flex-direction:column;padding:10px 28px 26px;gap:4px;
    transform:translateY(-8px);opacity:0;pointer-events:none;transition:.25s;
  }
  .mobile-menu.open{transform:none;opacity:1;pointer-events:auto;}
  .mobile-menu a{padding:14px 4px;font-size:16px;font-weight:600;border-bottom:1px solid var(--line);}
  .mobile-cta{display:flex;gap:10px;margin-top:16px;}
  .mobile-cta a{flex:1;text-align:center;padding:13px;border-radius:999px;font-weight:600;font-size:14.5px;}
  .mobile-cta .b1{background:#0B1222;color:#fff;}
  .mobile-cta .b2{border:1.5px solid var(--line);}

  /* ---------------- HERO ---------------- */
  .hero{
    position:relative;
    display:grid;grid-template-columns:1.08fr .92fr;gap:40px;align-items:center;
    padding:64px 56px 40px;max-width:1280px;margin:0 auto;
    --mx:50%;--my:30%;
  }
  .hero::before{
    content:'';position:absolute;inset:-1px;z-index:-1;pointer-events:none;
    background:radial-gradient(560px circle at var(--mx) var(--my), rgba(79,70,229,.16), transparent 62%);
    transition:opacity .4s ease;
    opacity:0;
  }
  .hero.spotlight-on::before{opacity:1;}
  .hero-badge{
    display:inline-flex;align-items:center;gap:9px;
    padding:7px 15px 7px 11px;border-radius:999px;border:1px solid var(--line);
    background:var(--card);font-size:13px;font-weight:600;color:var(--ink-soft);margin-bottom:26px;
  }
  .pulse{width:8px;height:8px;border-radius:50%;background:var(--emerald);position:relative;}
  .pulse::after{content:'';position:absolute;inset:0;border-radius:50%;background:var(--emerald);animation:pulse 1.8s ease-out infinite;}
  @keyframes pulse{0%{transform:scale(1);opacity:.7;}100%{transform:scale(2.6);opacity:0;}}

  .hero-h1{
    font-size:clamp(2.5rem,5.6vw,4.85rem);
    font-weight:700;line-height:.98;letter-spacing:-0.025em;margin:0 0 24px;
  }
  .hero-sub{font-size:18px;line-height:1.65;color:var(--ink-soft);max-width:520px;margin:0 0 34px;}
  .hero-cta{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:38px;}
  .btn-primary{
    display:inline-flex;align-items:center;gap:9px;
    background:#0B1222;color:#fff;font-weight:600;font-size:15px;
    padding:15px 26px;border-radius:999px;transition:transform .25s,box-shadow .25s,background .4s;
  }
  .btn-primary:hover{background:var(--grad);transform:translateY(-2px);box-shadow:var(--shadow-sm);}
  .btn-secondary{
    display:inline-flex;align-items:center;gap:9px;
    border:1.5px solid var(--line);color:var(--ink);font-weight:600;font-size:15px;
    padding:15px 24px;border-radius:999px;transition:.25s;background:var(--card);
  }
  .btn-secondary:hover{border-color:var(--indigo);color:var(--indigo);}
  .social-proof{display:flex;align-items:center;gap:14px;font-size:13.5px;color:var(--ink-faint);font-weight:500;}
  .avatars{display:flex;}
  .avatar{width:32px;height:32px;border-radius:50%;border:2.5px solid var(--paper);}

  /* module deck */
  .deck-outer{position:relative;height:440px;}
  .deck{position:relative;width:100%;height:380px;}
  .deck-card{
    position:absolute;inset:0;border-radius:var(--radius-lg);
    padding:30px 30px;display:flex;flex-direction:column;justify-content:space-between;
    background:var(--card);border:1px solid var(--line);box-shadow:var(--shadow-lg);
    cursor:pointer;transition:transform .6s cubic-bezier(.22,1,.36,1),opacity .5s,box-shadow .4s;
  }
  .deck-card .dc-icon{width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:24px;}
  .deck-card .dc-title{font-family:'Space Grotesk';font-weight:700;font-size:22px;margin-top:20px;letter-spacing:-.01em;}
  .deck-card .dc-desc{font-size:14.5px;color:var(--ink-soft);line-height:1.55;margin-top:8px;}
  .deck-meta{display:flex;align-items:center;justify-content:space-between;margin-top:20px;}
  .deck-count{font-size:12.5px;letter-spacing:.1em;color:var(--ink-faint);}
  .deck-dots{display:flex;gap:7px;}
  .deck-dot{width:20px;height:4px;border-radius:2px;background:var(--line);cursor:pointer;transition:.3s;}
  .deck-dot.active{background:var(--grad);width:30px;}

  /* ---------------- floating card enhancement (added, same palette) ---------------- */
  .deck-outer{perspective:1700px;}
  .deck-card{
    will-change:transform;
    transform-style:preserve-3d;
  }
  .deck-card::before{
    content:'';
    position:absolute;
    inset:-18px;
    border-radius:calc(var(--radius-lg) + 18px);
    background:radial-gradient(65% 65% at 50% 18%, rgba(79,70,229,.22), transparent 72%);
    filter:blur(22px);
    z-index:-1;
    opacity:0;
    transition:opacity .5s ease;
    pointer-events:none;
  }
  .deck-card.is-floating::before{ opacity:1; }
  .deck-card .dc-icon{
    animation: dcFloat 4.2s ease-in-out infinite;
  }
  .deck-card:nth-of-type(2n) .dc-icon{ animation-duration:3.6s; animation-delay:.25s; }
  .deck-card:nth-of-type(3n) .dc-icon{ animation-duration:5s; animation-delay:.5s; }
  .deck-card:nth-of-type(4n) .dc-icon{ animation-duration:4.6s; animation-delay:.15s; }
  @keyframes dcFloat{
    0%,100%{ transform:translateY(0) rotate(0deg); }
    50%{ transform:translateY(-7px) rotate(-4deg); }
  }
  @media (prefers-reduced-motion: reduce){
    .deck-card .dc-icon{ animation:none; }
  }

  /* ---------------- TICKER ---------------- */
  .ticker-wrap{border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:hidden;padding:22px 0;background:var(--card);margin-top:8px;}
  .ticker-track{display:flex;gap:44px;width:max-content;animation:scroll 32s linear infinite;}
  @keyframes scroll{from{transform:translateX(0);}to{transform:translateX(-50%);}}
  .ticker-item{display:flex;align-items:center;gap:10px;font-family:'Space Grotesk';font-weight:600;font-size:15.5px;color:var(--ink-soft);white-space:nowrap;}
  .ticker-dot{width:6px;height:6px;border-radius:50%;background:var(--violet);}

  /* ---------------- SPLIT INTRO ---------------- */
  .split-intro{
    display:grid;grid-template-columns:.85fr 1.15fr;gap:60px;align-items:center;
    padding:110px 56px;max-width:1280px;margin:0 auto;
  }
  .preview-frame{position:relative;}
  .preview-frame img.dash-shot{transition:opacity .2s ease;}
  .dash-shot-dark{display:block !important;filter:invert(0.92) hue-rotate(180deg) brightness(0.9) contrast(0.92);border-radius:var(--radius-lg);}
  .dash-shot-light{display:none !important;}
  html[data-theme="light"] .dash-shot-dark{display:none !important;}
  html[data-theme="light"] .dash-shot-light{display:block !important;filter:none;}
  .preview-glow{position:absolute;inset:-40px;background:var(--grad);opacity:.18;filter:blur(60px);border-radius:40px;z-index:0;}
  .preview-frame img{position:relative;z-index:1;border-radius:var(--radius-lg);border:1px solid var(--line);box-shadow:var(--shadow-lg);}
  .float-chip{
    position:absolute;z-index:2;bottom:-22px;left:-22px;
    background:#0B1222;color:#fff;padding:14px 20px;border-radius:16px;
    font-size:13.5px;font-weight:600;display:flex;align-items:center;gap:10px;box-shadow:var(--shadow-lg);
  }
  .float-chip .fc-dot{width:7px;height:7px;border-radius:50%;background:var(--emerald);}

  /* ---------------- PORTFOLIO GRID ---------------- */
  .portfolio-section{padding:80px 56px 110px;max-width:1280px;margin:0 auto;}
  .portfolio-head{max-width:640px;margin-bottom:64px;}
  .portfolio-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;}
  .p-card{
    position:relative;overflow:hidden;
    background:var(--card);border:1px solid var(--line);border-radius:var(--radius-lg);
    padding:32px 28px 30px;transition:transform .45s cubic-bezier(.22,1,.36,1),box-shadow .45s,border-color .45s;
  }
  .p-card::before{
    content:'';position:absolute;inset:0;background:var(--grad-soft);opacity:0;transition:opacity .45s;
  }
  .p-card:hover{transform:translateY(-8px);box-shadow:var(--shadow-lg);border-color:transparent;}
  .p-card:hover::before{opacity:1;}
  .p-index{font-family:'IBM Plex Mono';font-size:13px;color:var(--ink-faint);position:relative;z-index:1;}
  .p-icon{
    width:54px;height:54px;border-radius:15px;display:flex;align-items:center;justify-content:center;
    font-size:24px;margin:18px 0 20px;position:relative;z-index:1;transition:transform .4s;
  }
  .p-card:hover .p-icon{transform:scale(1.1) rotate(-4deg);}
  .p-title{font-family:'Space Grotesk';font-weight:700;font-size:20px;margin-bottom:10px;position:relative;z-index:1;letter-spacing:-.01em;}
  .p-desc{font-size:14.5px;line-height:1.6;color:var(--ink-soft);position:relative;z-index:1;}

  /* ---------------- AI SECTION (CENTERED) ---------------- */
  .ai-section{background:#0B1222;color:#fff;padding:110px 56px;text-align:center;}
  .ai-grid{display:flex;flex-direction:column;align-items:center;gap:40px;max-width:850px;margin:0 auto;}
  .ai-section .eyebrow{color:var(--violet);}
  .ai-section .section-sub{color:#B7B4CE;max-width:580px;margin:0 auto;}
  .bubble-stack{display:flex;flex-wrap:wrap;justify-content:center;gap:14px;}
  .bubble{
    background:#16151F;border:1px solid #2B2A3B;border-radius:999px;
    padding:12px 24px;font-size:14.5px;color:#E8E7F2;
    display:flex;align-items:center;gap:12px;
  }
  .bubble:nth-child(even){background:#1B1A2E;}
  .bubble-dot{width:7px;height:7px;border-radius:50%;background:var(--grad);flex:none;}

  /* ---------------- WHY GRID ---------------- */
  .why-section{padding:110px 56px;max-width:1280px;margin:0 auto;}
  .why-head{text-align:center;max-width:640px;margin:0 auto 60px;}
  .why-head .section-sub{margin:0 auto;}
  .why-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;}
  .w-card{
    --mx:50%;--my:50%;
    position:relative;overflow:hidden;background:var(--card);border:1px solid var(--line);
    border-radius:var(--radius-md);padding:28px 24px;transition:border-color .3s,transform .3s;
  }
  .w-card::before{
    content:'';position:absolute;inset:0;
    background:radial-gradient(220px circle at var(--mx) var(--my),rgba(124,92,252,.16),transparent 70%);
    opacity:0;transition:opacity .3s;
  }
  .w-card:hover{transform:translateY(-4px);border-color:var(--violet);}
  .w-card:hover::before{opacity:1;}
  .w-icon{width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:20px;position:relative;z-index:1;}
  .w-title{font-family:'Space Grotesk';font-weight:700;font-size:16.5px;margin:16px 0 8px;position:relative;z-index:1;}
  .w-desc{font-size:13.5px;color:var(--ink-soft);line-height:1.55;position:relative;z-index:1;}

  /* ---------------- SECURITY SPLIT ---------------- */
  .security-section{padding:40px 56px 110px;max-width:1280px;margin:0 auto;}
  .security-grid{display:grid;grid-template-columns:1fr .85fr;gap:60px;align-items:center;}
  .tag-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px;}
  .tag{
    font-size:13px;font-weight:600;padding:9px 15px;border-radius:999px;
    border:1px solid var(--line);color:var(--ink-soft);background:var(--card);
  }
  .badge-panel{
    background:#0B1222;border-radius:var(--radius-lg);padding:48px 36px;position:relative;overflow:hidden;
    box-shadow:var(--shadow-lg);
  }
  .badge-panel::before{content:'';position:absolute;top:-60px;right:-60px;width:220px;height:220px;border-radius:50%;background:var(--grad);opacity:.35;filter:blur(50px);}
  .badge-ring{
    width:104px;height:104px;border-radius:50%;border:1.5px solid #3A3852;
    display:flex;align-items:center;justify-content:center;position:relative;z-index:1;margin-bottom:26px;
  }
  .badge-ring-inner{width:74px;height:74px;border-radius:50%;background:var(--grad);display:flex;align-items:center;justify-content:center;font-size:30px;}
  .badge-panel h3{font-family:'Space Grotesk';color:#fff;font-size:22px;margin:0 0 10px;position:relative;z-index:1;}
  .badge-panel p{color:#B7B4CE;font-size:14px;line-height:1.6;position:relative;z-index:1;margin:0;}

  /* ---------------- INDUSTRIES ---------------- */
  .industries-section{padding:70px 56px 40px;max-width:1280px;margin:0 auto;text-align:center;}
  .industries-section .portfolio-head{margin:0 auto 44px;}
  .industry-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;text-align:left;}
  .industry-card{
    background:var(--card);border:1px solid var(--line);border-radius:16px;
    padding:20px;transition:.3s;
  }
  .industry-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg);border-color:transparent;}
  .industry-icon{
    width:42px;height:42px;border-radius:11px;display:flex;align-items:center;justify-content:center;
    font-size:19px;margin-bottom:12px;
  }
  .industry-card h3{font-family:'Space Grotesk';font-size:16.5px;margin:0 0 6px;color:var(--ink);}
  .industry-card p{font-size:13.5px;line-height:1.55;color:var(--ink-soft);margin:0;}

  /* ---------------- CONTACT ---------------- */
  .contact-section{padding:40px 56px 110px;max-width:1000px;margin:0 auto;text-align:center;}
  .contact-section .portfolio-head{margin:0 auto 40px;}
  .contact-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-bottom:36px;}
  .contact-card{
    background:var(--card);border:1px solid var(--line);border-radius:16px;
    padding:26px 20px;transition:.3s;
  }
  .contact-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg);}
  .contact-icon{font-size:24px;margin-bottom:10px;}
  .contact-label{font-family:'IBM Plex Mono',monospace;font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-faint);margin-bottom:8px;}
  .contact-value{font-family:'Space Grotesk';font-size:16px;font-weight:600;color:var(--ink);}
  a.contact-value:hover{color:var(--violet);}
  .contact-actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;}

  /* ---------------- PRICING ---------------- */
  .pricing-section{padding:70px 56px 110px;max-width:1280px;margin:0 auto;}
  .pricing-section .portfolio-head{text-align:center;margin:0 auto 60px;}
  .pricing-section .portfolio-head .eyebrow{justify-content:center;}
  .pricing-section .section-sub{margin:0 auto;}
  .pricing-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;align-items:stretch;}
  .price-card{
    position:relative;display:flex;flex-direction:column;
    background:var(--card);border:1px solid var(--line);border-radius:var(--radius-lg);
    padding:32px 26px 28px;transition:transform .4s cubic-bezier(.22,1,.36,1),box-shadow .4s,border-color .4s;
  }
  .price-card:hover{transform:translateY(-6px);box-shadow:var(--shadow-sm);}
  .price-card.featured{
    border-color:transparent;
    background:
      linear-gradient(var(--card),var(--card)) padding-box,
      var(--grad) border-box;
    border:1.5px solid transparent;
    box-shadow:var(--shadow-lg);
  }
  .price-card.featured:hover{transform:translateY(-10px);}
  .price-badge{
    position:absolute;top:-13px;right:26px;
    font-family:'IBM Plex Mono';font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;
    color:#fff;background:var(--grad);padding:6px 13px;border-radius:999px;
    box-shadow:0 8px 20px -8px rgba(79,70,229,.65);
  }
  .price-name{font-family:'Space Grotesk';font-weight:700;font-size:18px;letter-spacing:-.01em;color:var(--ink-soft);}
  .price-amount{display:flex;align-items:baseline;gap:6px;margin:16px 0 14px;font-family:'Space Grotesk';}
  .price-amount .amt{font-size:38px;font-weight:700;letter-spacing:-.02em;color:var(--ink);}
  .price-amount .per{font-size:14px;font-weight:500;color:var(--ink-faint);}
  .price-desc{font-size:14px;line-height:1.6;color:var(--ink-soft);min-height:66px;margin:0 0 22px;}
  .price-features{display:flex;flex-direction:column;gap:13px;margin-bottom:28px;flex:1;}
  .price-features li{display:flex;align-items:flex-start;gap:10px;font-size:14px;color:var(--ink);}
  .price-features svg{flex:none;margin-top:2px;color:var(--indigo);}
  .price-cta{
    display:block;text-align:center;font-size:14.5px;font-weight:600;
    padding:13px 20px;border-radius:999px;transition:.25s;
    border:1.5px solid var(--line);color:var(--ink);background:transparent;
  }
  .price-cta:hover{border-color:var(--indigo);color:var(--indigo);}
  .price-cta.primary{border-color:transparent;background:var(--grad);color:#fff;}
  .price-cta.primary:hover{filter:brightness(1.08);color:#fff;}

  @media (max-width:980px){
    .pricing-grid{grid-template-columns:repeat(2,1fr);}
  }
  @media (max-width:640px){
    .pricing-section{padding:56px 28px 70px;}
    .pricing-grid{grid-template-columns:1fr;}
    .price-card.featured{transform:none;}
  }

  /* ---------------- CTA ---------------- */
  .cta-section{padding:0 56px 100px;max-width:1280px;margin:0 auto;}
  .cta-card{
    position:relative;overflow:hidden;border-radius:36px;background:#0B1222;
    padding:100px 40px;text-align:center;
  }
  .cta-blob{position:absolute;width:340px;height:340px;border-radius:50%;filter:blur(70px);pointer-events:none;}
  .cta-blob.b1{background:var(--indigo-2);opacity:.5;top:-120px;left:-80px;}
  .cta-blob.b2{background:var(--blue);opacity:.4;bottom:-120px;right:-60px;}
  .cta-h2{position:relative;z-index:1;font-size:clamp(2.1rem,4.6vw,3.6rem);color:#fff;font-weight:700;line-height:1.04;letter-spacing:-.02em;margin:0 0 20px;}
  .cta-sub{position:relative;z-index:1;color:#B7B4CE;font-size:16.5px;max-width:520px;margin:0 auto 36px;line-height:1.6;}
  .cta-actions{position:relative;z-index:1;display:flex;gap:14px;justify-content:center;flex-wrap:wrap;}
  .cta-actions .btn-primary{background:#fff;color:#0A0B0F;}
  .cta-actions .btn-primary:hover{background:var(--grad);color:#fff;}
  .cta-actions .btn-secondary{border-color:#3A3852;color:#fff;background:transparent;}
  .cta-actions .btn-secondary:hover{border-color:#fff;}

  /* ---------------- FOOTER ---------------- */
  footer{border-top:1px solid var(--line);padding:56px 56px 40px;}
  .footer-grid{max-width:1280px;margin:0 auto;display:grid;grid-template-columns:1.3fr 1fr;gap:40px;padding-bottom:34px;}
  .footer-brand{display:flex;align-items:center;gap:10px;font-family:'Space Grotesk';font-weight:700;font-size:18px;margin-bottom:16px;}
  .footer-brand img{width:26px;height:26px;border-radius:7px;}
  .footer-grid p{color:var(--ink-soft);font-size:14.5px;line-height:1.65;max-width:460px;margin:0;}
  .footer-links{display:flex;gap:26px;justify-content:flex-end;align-items:flex-start;font-size:14px;color:var(--ink-soft);font-weight:500;}
  .footer-links a:hover{color:var(--indigo);}
  .footer-bottom{max-width:1280px;margin:0 auto;padding-top:26px;border-top:1px solid var(--line);font-size:13px;color:var(--ink-faint);}

  /* ---------------- RESPONSIVE ---------------- */
  @media (max-width:980px){
    .wrap,.hero,.split-intro,.ai-grid,.security-grid,.footer-grid{grid-template-columns:1fr !important;}
    .hero{gap:40px;padding:40px 24px 20px;}
    .split-intro{padding:56px 24px;gap:32px;}
    .split-intro .preview-frame{order:-1;}
    .portfolio-grid{grid-template-columns:repeat(2,1fr);}
    .why-grid{grid-template-columns:repeat(2,1fr);}
    .ai-section{padding:56px 24px;}
    .security-section{padding:20px 24px 56px;}
    .industries-section,.portfolio-section,.pricing-section{padding:48px 24px 56px;}
    .cta-section{padding:0 20px 56px;}
    .cta-card{padding:56px 24px;}
    .footer-links{justify-content:flex-start;flex-wrap:wrap;gap:16px;}
    nav{padding:16px 20px;}
    .nav-links{display:none;}
    .hamburger{display:flex;}
    .mobile-menu{display:flex;}
    .pricing-grid{grid-template-columns:repeat(2,1fr);}
  }
  @media (max-width:640px){
    .portfolio-grid,.why-grid,.pricing-grid,.contact-grid,.industry-grid{grid-template-columns:1fr !important;}
    .hero{padding:24px 16px 16px;}
    .hero-h1{font-size: clamp(2.2rem, 8vw, 3rem); line-height: 1.1;}
    .hero-cta{flex-direction:column;align-items:stretch;}
    .hero-cta > * {width: 100%; text-align: center;}
    .deck-outer{height:300px;}
    .float-chip{left:8px;bottom:-16px;font-size:11px;padding:8px 12px;}
    .split-intro,.ai-section,.security-section,.industries-section,.portfolio-section,.pricing-section{padding:40px 16px; gap:24px;}
    .cta-section{padding:0 16px 40px;}
    .cta-card{padding:40px 20px; border-radius: 24px;}
    .cta-actions {flex-direction: column; align-items: stretch;}
    .cta-actions > * {width: 100%; text-align: center;}
    footer{padding:32px 16px 24px;}
    .price-card.featured{transform:none;}
    .section-h2{font-size: clamp(1.8rem, 7vw, 2.5rem);}
    .bubble{font-size: 14px; padding: 12px 16px;}
    .footer-grid{gap: 24px;}
    nav{padding:12px 16px;}
  }

  /* ---------------- LIGHT THEME (added) ---------------- */
  html[data-theme="light"]{
    --ink:#0A0B0F;
    --ink-soft:#64748b;
    --ink-faint:#94a3b8;
    --paper:#F9FAFB;
    --card:#FFFFFF;
    --line:rgba(109,91,208,0.22);
    --shadow-lg: 0 30px 70px -30px rgba(79,70,229,.28);
    --shadow-sm: 0 10px 30px -14px rgba(79,70,229,.20);
    --card-overlay: linear-gradient(rgba(255, 255, 255, 0.15) 0%, rgba(255, 255, 255, 0.75) 100%);
  }
  html[data-theme="light"] nav#mainNav{background:var(--paper);}
  html[data-theme="light"] nav#mainNav.scrolled{box-shadow:0 8px 30px -20px rgba(79,70,229,.35);}
  html[data-theme="light"] .mobile-menu{background:var(--paper);}
  html[data-theme="light"] .ai-section{background:#F5F3FF;color:var(--ink);}
  html[data-theme="light"] .ai-section .section-sub{color:var(--ink-soft);}
  html[data-theme="light"] .bubble{
    background:#FFFFFF;
    border:1px solid rgba(109,91,208,0.15);
    color:var(--ink);
    box-shadow: 0 4px 12px rgba(79,70,229,0.04);
  }
  html[data-theme="light"] .bubble:nth-child(even){background:#EEF2F6;}
  html[data-theme="light"] .badge-panel{
    background:var(--card);
    border:1px solid var(--line);
    box-shadow:var(--shadow-lg);
  }
  html[data-theme="light"] .badge-panel h3{color:var(--ink);}
  html[data-theme="light"] .badge-panel p{color:var(--ink-soft);}
  html[data-theme="light"] .badge-ring{border:1.5px solid var(--line);}
  html[data-theme="light"] .badge-panel::before{opacity:0.15;}

  html[data-theme="light"] .cta-card{
    background:#F5F3FF;
    border:1px solid var(--line);
    box-shadow:var(--shadow-lg);
  }
  html[data-theme="light"] .cta-h2{color:var(--ink);}
  html[data-theme="light"] .cta-sub{color:var(--ink-soft);}
  html[data-theme="light"] .cta-actions .btn-primary{background:var(--ink);color:#fff;}
  html[data-theme="light"] .cta-actions .btn-primary:hover{background:var(--grad);}
  html[data-theme="light"] .cta-actions .btn-secondary{border-color:var(--line);color:var(--ink);}

  /* ---------------- THEME TOGGLE BUTTON ---------------- */
  .theme-toggle{
    display:flex;align-items:center;justify-content:center;
    width:40px;height:40px;border-radius:10px;
    border:1.5px solid var(--line);background:var(--card);
    color:var(--ink);cursor:pointer;transition:.2s;flex:none;
  }
  .theme-toggle:hover{border-color:var(--violet);}
  .theme-toggle svg{width:18px;height:18px;}
  .theme-toggle .icon-sun{display:none;}
  .theme-toggle .icon-moon{display:block;}
  html[data-theme="light"] .theme-toggle .icon-sun{display:block;}
  html[data-theme="light"] .theme-toggle .icon-moon{display:none;}
  .mobile-theme-toggle{
    display:flex;align-items:center;gap:10px;
    padding:13px 4px;border-bottom:1px solid var(--line);
    font-size:15px;color:var(--ink);cursor:pointer;background:none;border-left:none;border-right:none;border-top:none;width:100%;text-align:left;font-family:inherit;
  }
  .mobile-theme-toggle svg{width:17px;height:17px;flex:none;}
  .mobile-theme-toggle .icon-sun{display:none;}
  .mobile-theme-toggle .icon-moon{display:block;}
  html[data-theme="light"] .mobile-theme-toggle .icon-sun{display:block;}
  html[data-theme="light"] .mobile-theme-toggle .icon-moon{display:none;}

  /* ---------------- CARD OVERLAY EXTENSIONS ---------------- */
  .deck-card[style*="--bg-image"]::before, .p-card[style*="--bg-image"]::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: var(--bg-image);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 0;
    border-radius: inherit;
    pointer-events: none;
    transition: filter 0.4s ease;
  }
  .deck-card[style*="--bg-image"]::after, .p-card[style*="--bg-image"]::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: var(--card-overlay);
    z-index: 1;
    border-radius: inherit;
    pointer-events: none;
  }
  .deck-card > *, .p-card > * {
    position: relative;
    z-index: 2;
  }
  html[data-theme="light"] .deck-card::before,
  html[data-theme="light"] .p-card::before {
    filter: invert(0.9) hue-rotate(180deg) brightness(1.15) contrast(0.85);
  }
`;

