function DashboardPreviewPortal() {
  const [activeIndex, setActiveIndex] = useState(0);
  const [nodes, setNodes] = useState({ switcher: null, deck0: null, deck1: null, deck2: null, deck3: null, deck4: null });

  useEffect(() => {
    setTimeout(() => {
      setNodes({
        switcher: document.getElementById('dashboard-preview-root'),
        deck0: document.getElementById('deck-bg-0'),
        deck1: document.getElementById('deck-bg-1'),
        deck2: document.getElementById('deck-bg-2'),
        deck3: document.getElementById('deck-bg-3'),
        deck4: document.getElementById('deck-bg-4'),
      });
    }, 0);
    
    const handleUpdate = (e) => setActiveIndex(e.detail);
    window.addEventListener('aminoid-preview-change', handleUpdate);
    return () => window.removeEventListener('aminoid-preview-change', handleUpdate);
  }, []);

  return (
    <>
      {nodes.switcher && createPortal(<DashboardSwitcher activeIndex={activeIndex} />, nodes.switcher)}
      {nodes.deck0 && createPortal(<HRPreview />, nodes.deck0)}
      {nodes.deck1 && createPortal(<SalesPreview />, nodes.deck1)}
      {nodes.deck2 && createPortal(<ProjectsPreview />, nodes.deck2)}
      {nodes.deck3 && createPortal(<FinancePreview />, nodes.deck3)}
      {nodes.deck4 && createPortal(<AnalyticsPreview />, nodes.deck4)}
    </>
  );
}

